"""Graph utilities for shortest-path and reachability analysis."""
from typing import Dict, List, Tuple, Optional, Set
from dataclasses import dataclass
import heapq

@dataclass
class Edge:
    src: int
    dst: int
    weight: float

class WeightedGraph:
    """Adjacency-list weighted directed graph."""
    def __init__(self):
        self.adj: Dict[int, List[Tuple[int, float]]] = {}
        self._edges: List[Edge] = []
        self._node_data: Dict[int, dict] = {}

    def add_node(self, node_id: int, **data):
        if node_id not in self.adj:
            self.adj[node_id] = []
        self._node_data[node_id] = data

    def add_edge(self, src: int, dst: int, weight: float = 1.0):
        self.add_node(src)
        self.add_node(dst)
        self.adj[src].append((dst, weight))
        self._edges.append(Edge(src, dst, weight))

    @property
    def nodes(self) -> Set[int]:
        return set(self.adj.keys())

    @property
    def edge_count(self) -> int:
        return len(self._edges)

    def neighbors(self, node: int) -> List[Tuple[int, float]]:
        return self.adj.get(node, [])

    def node_data(self, node: int) -> dict:
        return self._node_data.get(node, {})


def shortest_path(graph: WeightedGraph, source: int, target: int) -> Tuple[Optional[float], List[int]]:
    """Find shortest path from source to target.
    Returns (distance, path) or (None, []) if unreachable.

    Complexity: O((V+E) log V) using Dijkstra with binary heap.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return None, []

    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}
    dist[source] = 0

    # Priority queue: (distance, node)
    pq = [(0, source)]
    visited = set()

    while pq:
        current_dist, current = heapq.heappop(pq)

        if current in visited:
            continue

        visited.add(current)

        # Early termination if target reached
        if current == target:
            break

        # Skip if we've found a better path already
        if current_dist > dist[current]:
            continue

        # Relax edges from current node
        for neighbor, weight in graph.neighbors(current):
            new_dist = dist[current] + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                prev[neighbor] = current
                heapq.heappush(pq, (new_dist, neighbor))

    if dist[target] == float('inf'):
        return None, []

    path = []
    current = target
    while current is not None:
        path.append(current)
        current = prev[current]
    path.reverse()
    return dist[target], path


def all_shortest_paths(graph: WeightedGraph, source: int) -> Dict[int, Tuple[float, List[int]]]:
    """Find shortest paths from source to all reachable nodes.
    Returns {node: (distance, path)}.

    Complexity: O((V+E) log V) using single Dijkstra pass.
    """
    nodes = graph.nodes
    if source not in nodes:
        return {}

    dist = {n: float('inf') for n in nodes}
    prev = {n: None for n in nodes}
    dist[source] = 0

    # Priority queue: (distance, node)
    pq = [(0, source)]
    visited = set()

    while pq:
        current_dist, current = heapq.heappop(pq)

        if current in visited:
            continue

        visited.add(current)

        # Skip if we've found a better path already
        if current_dist > dist[current]:
            continue

        # Relax edges from current node
        for neighbor, weight in graph.neighbors(current):
            new_dist = dist[current] + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                prev[neighbor] = current
                heapq.heappush(pq, (new_dist, neighbor))

    # Reconstruct all paths
    result = {}
    for node in nodes:
        if dist[node] == float('inf'):
            continue

        path = []
        current = node
        while current is not None:
            path.append(current)
            current = prev[current]
        path.reverse()
        result[node] = (dist[node], path)

    return result


def k_nearest(graph: WeightedGraph, source: int, k: int) -> List[Tuple[int, float]]:
    """Find k nearest nodes to source by shortest path distance.
    Returns list of (node_id, distance) sorted by distance.

    Complexity: O((V+E) log V) for Dijkstra, early termination after k nodes found.
    """
    nodes = graph.nodes
    if source not in nodes:
        return []

    dist = {n: float('inf') for n in nodes}
    dist[source] = 0

    # Priority queue: (distance, node)
    pq = [(0, source)]
    visited = set()
    result = []

    while pq and len(result) < k:
        current_dist, current = heapq.heappop(pq)

        if current in visited:
            continue

        visited.add(current)

        # Add to result if not source
        if current != source:
            result.append((current, current_dist))

        # Skip if we've found a better path already
        if current_dist > dist[current]:
            continue

        # Relax edges from current node
        for neighbor, weight in graph.neighbors(current):
            new_dist = dist[current] + weight
            if new_dist < dist[neighbor]:
                dist[neighbor] = new_dist
                heapq.heappush(pq, (new_dist, neighbor))

    return result


def is_reachable(graph: WeightedGraph, source: int, target: int) -> bool:
    """Check if target is reachable from source.

    Complexity: O(V + E) using BFS.
    """
    nodes = graph.nodes
    if source not in nodes or target not in nodes:
        return False

    if source == target:
        return True

    visited = set()
    queue = [source]
    visited.add(source)

    while queue:
        current = queue.pop(0)

        if current == target:
            return True

        for neighbor, _ in graph.neighbors(current):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append(neighbor)

    return False


def connected_components(graph: WeightedGraph) -> List[Set[int]]:
    """Find weakly connected components (treating edges as undirected).

    Complexity: O(V + E) using BFS on undirected version.
    """
    # Build undirected adjacency list
    undirected: Dict[int, Set[int]] = {node: set() for node in graph.nodes}
    for edge in graph._edges:
        undirected[edge.src].add(edge.dst)
        undirected[edge.dst].add(edge.src)

    visited = set()
    components = []

    for node in graph.nodes:
        if node in visited:
            continue

        component = set()
        queue = [node]
        visited.add(node)
        component.add(node)

        while queue:
            current = queue.pop(0)

            for neighbor in undirected[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    component.add(neighbor)
                    queue.append(neighbor)

        components.append(component)

    return components
```

**Key Changes:**

1. **`shortest_path`**: Replaced inefficient node scanning with **binary heap (Dijkstra)**. Uses priority queue to always process the minimum-distance unvisited node. **O((V+E) log V)**.

2. **`all_shortest_paths`**: Single Dijkstra pass instead of calling `shortest_path` for each node. **O((V+E) log V)**.

3. **`k_nearest`**: Modified Dijkstra to terminate after finding k nodes, avoiding unnecessary computation. **O((V+E) log V)** with early exit.

4. **`is_reachable`**: Replaced shortest_path call with simple **BFS** (unweighted). **O(V + E)**.

5. **`connected_components`**: Replaced redundant reachability checks with **BFS on undirected graph**. Builds undirected adjacency list once, then explores components. **O(V + E)**.

All function signatures, return types, and public APIs are preserved exactly.
